import "dotenv/config";
import express from "express";
import cors from "cors";
import { runAnalysisPipeline } from "./domain/analysis/runAnalysisPipeline.js";

const app = express();
app.use(cors({ origin: "*" }));
app.use(express.json({ limit: "5mb" }));

app.get("/health", (_, res) => res.json({ ok: true }));

app.post("/documents/:documentId/analyze", async (req, res) => {
  try {
    const { text, role, language } = req.body || {};
    const result = await runAnalysisPipeline({
      fullText: text || "sample agreement",
      userRole: role || "student",
      outputLanguage: language || "en"
    });
    res.status(200).json({ documentId: req.params.documentId, ...result });
  } catch (e: any) {
    res.status(500).json({ message: e?.message || "failed" });
  }
});

app.get("/dashboard/summary", (_, res) => {
  res.json({ totalDocuments: 3, highRiskCount: 1, moderateRiskCount: 1, safeCount: 1, upcomingObligations: 2 });
});

const port = process.env.PORT || 4000;
app.listen(port, () => console.log(`API running on :${port}`));